1	//! The GitHub Releases read path: argv, HTTP framing, and response parsing.
2	//!
3	//! Kept free of any provider so the forge-release and artifact-upload roles
4	//! share one lookup and cannot drift in how they read an absence.
5	
6	use std::path::Path;
7	
8	use callisto_model::{CommandOutput, CommandRunner, TagName};
9	
10	use crate::error::CommandFailure;
11	use crate::GraphError;
12	
13	use super::provider::http::{parse_http_response, HttpResponse};
14	use super::provider::policy::{programs, retry_observation, run_observation, timeouts, Attempt, Sleeper};
15	
16	/// One GitHub release lookup, shared by the forge-release and asset adapters.
17	#[derive(Debug)]
18	pub(crate) enum GitHubReleaseLookup {
19	    Absent,
20	    Indeterminate {
21	        status: u16,
22	    },
23	    /// `gh api` failed to run at all, so there is no HTTP status to report, unlike [`Self::Indeterminate`].
24	    CommandFailed,
25	    Found(serde_json::Value),
26	}
27	
28	pub(crate) fn github_release_endpoint(repository: &str, id: u64) -> String {
29	    format!("repos/{repository}/releases/{id}")
30	}
31	
32	/// Finds drafts too, unlike `GET /releases/tags/{tag}`.
33	const RELEASE_ID_QUERY: &str = "query($owner:String!,$name:String!,$tagName:String!)\
34	{repository(owner:$owner,name:$name){release(tagName:$tagName){databaseId}}}";
35	
36	/// `gh api` defines no `--repo`; the endpoint already carries owner and repository.
37	pub(crate) fn github_release_api_args(endpoint: &str) -> [&str; 5] {
38	    ["api", "--include", "--method", "GET", endpoint]
39	}
40	
41	fn parse_github_api_response(program: &str, args: &[&str], stdout: &str) -> Result<HttpResponse, GraphError> {
42	    parse_http_response(stdout).map_err(|detail| GraphError::ReleaseCommand {
43	        program: program.to_string(),
44	        args: args.iter().map(ToString::to_string).collect(),
45	        failure: CommandFailure::MalformedOutput { detail },
46	    })
47	}
48	
49	/// `gh api --include` preserves the HTTP response even for a 404 and exits
50	/// non-zero. Parse that authoritative response first so absence is not
51	/// mistaken for a transport failure; retain the command failure when no
52	/// parseable HTTP response was produced.
53	fn github_api_response(program: &str, args: &[&str], output: &CommandOutput) -> Result<HttpResponse, GraphError> {
54	    match parse_github_api_response(program, args, &output.stdout) {
55	        Ok(response) => Ok(response),
56	        Err(_) if !output.success() => Err(GraphError::ReleaseCommand {
57	            program: program.to_owned(),
58	            args: args.iter().map(ToString::to_string).collect(),
59	            failure: CommandFailure::NonZeroExit {
60	                exit_code: output.exit_code,
61	                stderr: output.stderr.clone(),
62	            },
63	        }),
64	        Err(error) => Err(error),
65	    }
66	}
67	
68	/// Classifies an HTTP response before parsing a GitHub Release body. A 404
69	/// proves absence; all other non-success statuses leave remote identity
70	/// unknown. In particular, authentication, rate-limit, and server failures
71	/// must never be reported as a conflicting release or asset.
72	fn github_release_response_status(status: u16) -> Option<GitHubReleaseLookup> {
73	    match status {
74	        200 => None,
75	        404 => Some(GitHubReleaseLookup::Absent),
76	        other => Some(GitHubReleaseLookup::Indeterminate { status: other }),
77	    }
78	}
79	
80	/// GraphQL for the release ID by tag, then REST by ID: how `gh release view` finds drafts.
81	pub(crate) fn github_release_for_tag(
82	    root: &Path,
83	    runner: &dyn CommandRunner,
84	    sleeper: &dyn Sleeper,
85	    repository: &str,
86	    tag: &TagName,
87	) -> Result<GitHubReleaseLookup, GraphError> {
88	    let id = match retry_observation(sleeper, || github_release_id_once(root, runner, repository, tag))? {
89	        ReleaseIdLookup::Found(id) => id,
90	        ReleaseIdLookup::Unknown(lookup) => return Ok(lookup),
91	    };
92	    let endpoint = github_release_endpoint(repository, id);
93	    retry_observation(sleeper, || github_api_get_once(root, runner, &endpoint))
94	}
95	
96	enum ReleaseIdLookup {
97	    Found(u64),
98	    Unknown(GitHubReleaseLookup),
99	}
100	
101	fn github_release_id_once(
102	    root: &Path,
103	    runner: &dyn CommandRunner,
104	    repository: &str,
105	    tag: &TagName,
106	) -> Result<Attempt<ReleaseIdLookup>, GraphError> {
107	    let (owner, name) = repository
108	        .split_once('/')
109	        .ok_or_else(|| malformed_github_response(repository, "GitHub repository is not OWNER/NAME"))?;
110	    let query = format!("query={RELEASE_ID_QUERY}");
111	    let owner = format!("owner={owner}");
112	    let name = format!("name={name}");
113	    let tag_name = format!("tagName={tag}");
114	    let args = [
115	        "api",
116	        "--include",
117	        "graphql",
118	        "-f",
119	        &query,
120	        "-f",
121	        &owner,
122	        "-f",
123	        &name,
124	        "-f",
125	        &tag_name,
126	    ];
127	    let malformed = |detail: &str| GraphError::ReleaseCommand {
128	        program: programs::GH.to_owned(),
129	        args: args.iter().map(ToString::to_string).collect(),
130	        failure: CommandFailure::MalformedOutput {
131	            detail: detail.to_owned(),
132	        },
133	    };
134	    let transient = |value| {
135	        Ok(Attempt::Transient {
136	            value: ReleaseIdLookup::Unknown(value),
137	            retry_after: None,
138	        })
139	    };
140	    let observed = match run_observation(runner, programs::GH, &args, root, timeouts::FORGE_API, false)? {
141	        Ok(output) => output,
142	        Err(_unavailable) => return transient(GitHubReleaseLookup::CommandFailed),
143	    };
144	    let response = github_api_response(programs::GH, &args, &observed)?;
145	    if response.status != 200 {
146	        let lookup = GitHubReleaseLookup::Indeterminate {
147	            status: response.status,
148	        };
149	        return Ok(if response.is_transient() {
150	            Attempt::Transient {
151	                value: ReleaseIdLookup::Unknown(lookup),
152	                retry_after: response.retry_after(),
153	            }
154	        } else {
155	            Attempt::Settled(ReleaseIdLookup::Unknown(lookup))
156	        });
157	    }
158	    let value: serde_json::Value =
159	        serde_json::from_str(&response.body).map_err(|error| malformed(&error.to_string()))?;
160	    // GraphQL returns failures, rate limits included, as a 200 with `errors`.
161	    let repository_node = value.pointer("/data/repository").filter(|node| !node.is_null());
162	    let Some(repository_node) = repository_node.filter(|_| value.get("errors").is_none()) else {
163	        return transient(GitHubReleaseLookup::CommandFailed);
164	    };
165	    match repository_node.get("release") {
166	        Some(serde_json::Value::Null) => Ok(Attempt::Settled(ReleaseIdLookup::Unknown(GitHubReleaseLookup::Absent))),
167	        Some(release) => release
168	            .get("databaseId")
169	            .and_then(serde_json::Value::as_u64)
170	            .map(|id| Attempt::Settled(ReleaseIdLookup::Found(id)))
171	            .ok_or_else(|| malformed("GitHub release has no databaseId")),
172	        None => Err(malformed("GitHub response has no release field")),
173	    }
174	}
175	
176	pub(crate) fn malformed_github_response(endpoint: &str, detail: &str) -> GraphError {
177	    GraphError::ReleaseCommand {
178	        program: programs::GH.to_owned(),
179	        args: github_release_api_args(endpoint)
180	            .iter()
181	            .map(ToString::to_string)
182	            .collect(),
183	        failure: CommandFailure::MalformedOutput {
184	            detail: detail.to_owned(),
185	        },
186	    }
187	}
188	
189	fn github_api_get_once(
190	    root: &Path,
191	    runner: &dyn CommandRunner,
192	    endpoint: &str,
193	) -> Result<Attempt<GitHubReleaseLookup>, GraphError> {
194	    let api_args = github_release_api_args(endpoint);
195	    let observed = match run_observation(runner, programs::GH, &api_args, root, timeouts::FORGE_API, false)? {
196	        Ok(output) => output,
197	        Err(_unavailable) => {
198	            return Ok(Attempt::Transient {
199	                value: GitHubReleaseLookup::CommandFailed,
200	                retry_after: None,
201	            })
202	        }
203	    };
204	    let response = github_api_response(programs::GH, &api_args, &observed)?;
205	    if let Some(lookup) = github_release_response_status(response.status) {
206	        return Ok(if response.is_transient() {
207	            Attempt::Transient {
208	                value: lookup,
209	                retry_after: response.retry_after(),
210	            }
211	        } else {
212	            Attempt::Settled(lookup)
213	        });
214	    }
215	    let value: serde_json::Value =
216	        serde_json::from_str(&response.body).map_err(|error| GraphError::ReleaseCommand {
217	            program: programs::GH.to_string(),
218	            args: api_args.iter().map(ToString::to_string).collect(),
219	            failure: CommandFailure::MalformedOutput {
220	                detail: error.to_string(),
221	            },
222	        })?;
223	    Ok(Attempt::Settled(GitHubReleaseLookup::Found(value)))
224	}
