1	//! The artifact-upload role: one verified asset attached to a forge release.
2	
3	use callisto_model::{
4	    ExactEvidence, ProviderConflictReason, ProviderEvidenceV1, ProviderIndeterminateCause, ProviderObservationV1,
5	};
6	
7	use crate::error::{CommandFailure, ReleasePreconditionRequirement, RemoteConflict};
