15	use super::{
16	    confirmed_evidence, wrong_role, ArtifactUploadOperation, EffectAuthorization, PreparedOperation,
17	    ProviderCapabilities, ProviderContext, ProviderRequest, ReleaseProvider,
18	};
19	
20	pub(crate) struct ArtifactUploadProvider;
21	
22	impl ReleaseProvider for ArtifactUploadProvider {
23	    fn capabilities(&self) -> ProviderCapabilities {
24	        ProviderCapabilities {
25	            can_observe: true,
26	            can_publish: true,
27	        }
28	    }
29	
30	    fn preflight_conflict(&self) -> RemoteConflict {
31	        RemoteConflict::ArtifactDiffers
32	    }
33	
34	    fn observe(
35	        &self,
36	        context: &ProviderContext<'_>,
37	        request: &ProviderRequest<'_>,
38	    ) -> Result<ProviderObservationV1, GraphError> {
39	        observe_artifact_upload(context, artifact_operation(request)?, request.artifacts)
40	    }
41	
42	    fn preflight(
43	        &self,
44	        context: &ProviderContext<'_>,
45	        request: &ProviderRequest<'_>,
46	    ) -> Result<super::ReleasePreflight, GraphError> {
47	        // An upload cannot be judged absent without the manifest that names
48	        // the exact bytes it would carry.
49	        request.artifacts.ok_or(GraphError::ReleasePreconditionUnmet {
50	            requirement: ReleasePreconditionRequirement::VerifiedArtifactManifest,
51	        })?;
52	        super::preflight_from_observation(self.observe(context, request)?, request.id, self.preflight_conflict())
53	    }
54	
55	    fn publish(
56	        &self,
57	        context: &ProviderContext<'_>,
58	        request: &ProviderRequest<'_>,
59	        _effect: &EffectAuthorization<'_>,
60	    ) -> Result<ExactEvidence, GraphError> {
61	        let operation = artifact_operation(request)?;
62	        let artifacts = request.artifacts.ok_or(GraphError::ReleasePreconditionUnmet {
63	            requirement: ReleasePreconditionRequirement::VerifiedArtifactManifest,
64	        })?;
65	        let path = artifacts.path_for(&operation.slot)?;
66	        let repository = operation.slot.attestation_policy.repository.as_slug();
67	        confirmed_evidence(
68	            observe_until_visible(context.sleeper(), || {
69	                observed_draft_or_published_release(context, &operation.tag, operation.prerelease, &repository)
70	            })?,
71	            request.id,
72	            RemoteConflict::ForgeReleaseNotObservedAfterCreate,
73	        )?;
74	        let path_argument = path.to_string_lossy();
75	        let args = [
76	            "release",
77	            "upload",
78	            operation.tag.as_str(),
79	            path_argument.as_ref(),
80	            "--repo",
81	            repository.as_str(),
82	        ];
83	        let uploaded =
84	            context
85	                .runner()
86	                .run_with_timeout(programs::GH, &args, context.root(), timeouts::FORGE_ASSET_UPLOAD)?;
87	        if !uploaded.success() {
88	            return Err(GraphError::ReleaseCommand {
89	                program: programs::GH.to_owned(),
90	                args: args.iter().map(ToString::to_string).collect(),
91	                failure: CommandFailure::NonZeroExit {
92	                    exit_code: uploaded.exit_code,
93	                    stderr: uploaded.stderr,
94	                },
95	            });
96	        }
97	        confirmed_evidence(
98	            observe_until_visible(context.sleeper(), || {
99	                observe_artifact_upload(context, operation, Some(artifacts))
100	            })?,
101	            request.id,
102	            RemoteConflict::ArtifactNotObservedAfterUpload,
103	        )
104	    }
105	}
106	
107	fn artifact_operation<'a>(request: &ProviderRequest<'a>) -> Result<&'a ArtifactUploadOperation, GraphError> {
108	    match request.operation {
109	        PreparedOperation::ArtifactUpload(operation) => Ok(operation),
110	        _ => Err(wrong_role(request.id, "artifact upload")),
111	    }
112	}
113	
114	fn observe_artifact_upload(
115	    context: &ProviderContext<'_>,
116	    operation: &ArtifactUploadOperation,
117	    artifacts: Option<&super::VerifiedArtifactManifest<'_>>,
118	) -> Result<ProviderObservationV1, GraphError> {
119	    let Some(artifacts) = artifacts else {
120	        return Ok(ProviderObservationV1::Indeterminate {
121	            cause: ProviderIndeterminateCause::ArtifactManifestUnavailable,
122	        });
123	    };
124	    let entry = artifacts.entry_for(&operation.slot)?;
125	    let repository = operation.slot.attestation_policy.repository.as_slug();
126	    let release = match github_release_for_tag(
127	        context.root(),
128	        context.runner(),
129	        context.sleeper(),
130	        &repository,
131	        &operation.tag,
132	    )? {
133	        GitHubReleaseLookup::Absent => return Ok(ProviderObservationV1::Absent),
134	        GitHubReleaseLookup::Indeterminate { status } => {
135	            return Ok(ProviderObservationV1::Indeterminate {
136	                cause: ProviderIndeterminateCause::ProviderStatus { status },
137	            })
138	        }
139	        GitHubReleaseLookup::CommandFailed => {
140	            return Ok(ProviderObservationV1::Indeterminate {
141	                cause: ProviderIndeterminateCause::CommandFailed,
142	            })
143	        }
144	        GitHubReleaseLookup::Found(release) => release,
145	    };
146	    let assets = release
147	        .get("assets")
148	        .and_then(serde_json::Value::as_array)
149	        .ok_or_else(|| {
150	            malformed_github_response(
151	                &github_release_endpoint(
152	                    &repository,
153	                    release
154	                        .get("id")
155	                        .and_then(serde_json::Value::as_u64)
156	                        .unwrap_or_default(),
157	                ),
158	                "GitHub release response has no assets array",
159	            )
160	        })?;
161	    let matching: Vec<_> = assets
162	        .iter()
163	        .filter(|asset| {
164	            asset.get("name").and_then(serde_json::Value::as_str) == Some(operation.slot.asset_name.as_str())
165	        })
166	        .collect();
167	    match matching.as_slice() {
168	        [] => Ok(ProviderObservationV1::Absent),
169	        [asset] => {
170	            let digest = format!("sha256:{}", entry.digest.as_str());
171	            if asset.get("size").and_then(serde_json::Value::as_u64) == Some(entry.byte_length)
172	                && asset.get("digest").and_then(serde_json::Value::as_str) == Some(digest.as_str())
173	            {
174	                Ok(ProviderObservationV1::Exact {
175	                    evidence: ProviderEvidenceV1::ArtifactUpload {
176	                        byte_length: entry.byte_length,
177	                        sha256: entry.digest.clone(),
178	                    },
179	                })
180	            } else {
181	                Ok(ProviderObservationV1::Conflict {
182	                    reason: ProviderConflictReason::ArtifactAssetDiffers,
183	                })
184	            }
185	        }
186	        _ => Ok(ProviderObservationV1::Conflict {
187	            reason: ProviderConflictReason::DuplicateArtifactAsset,
188	        }),
189	    }
190	}
