1	//! The registry-publish role: one adapter per ecosystem, selected once.
2	
3	use std::sync::Arc;
4	use std::time::Duration;
5	
6	use callisto_model::{
7	    normalize_pypi_project_name, CommandOutput, Ecosystem, ExactEvidence, ProviderConflictReason, ProviderEvidenceV1,
8	    ProviderIndeterminateCause, ProviderObservationV1, PublishOutcome, RegistryError, RegistryKey, ReleaseOperationId,
9	    Version,
10	};
11	
12	use crate::commands::registry_argv;
13	use crate::error::{CommandFailure, ReleasePreconditionRequirement, RemoteConflict, UnsupportedReleaseFeature};
14	use crate::GraphError;
15	
16	use super::http::parse_http_response;
17	use super::policy::{self, programs, require_registry_confirmation, run_observation, timeouts, Attempt};
18	use super::pypi_files::{self, BuiltFile, BuiltSet, PypiSimpleFile, PypiSimpleIndex};
19	use super::repository;
20	use super::{
21	    preflight_from_observation, wrong_role, EffectAuthorization, PreparedOperation, ProviderCapabilities,
22	    ProviderContext, ProviderRequest, RegistryPublishOperation, ReleasePreflight, ReleaseProvider,
23	    VerifiedArtifactManifest,
24	};
25	
26	pub(crate) struct RegistryProvider;
27	
28	impl ReleaseProvider for RegistryProvider {
29	    fn capabilities(&self) -> ProviderCapabilities {
30	        // Every registry answers an observation. Whether that answer can be
31	        // exact is the adapter's `can_observe_versions`.
32	        ProviderCapabilities {
33	            can_observe: true,
34	            can_publish: true,
35	        }
36	    }
37	
38	    fn observe(
39	        &self,
40	        context: &ProviderContext<'_>,
41	        request: &ProviderRequest<'_>,
42	    ) -> Result<ProviderObservationV1, GraphError> {
43	        let operation = registry_operation(request)?;
44	        registry_observation(adapter_for(request.id.package.ecosystem())?, context, operation)
45	    }
46	
47	    fn preflight_conflict(&self) -> RemoteConflict {
48	        RemoteConflict::RegistryVersionDiffers
49	    }
50	
51	    fn preflight(
52	        &self,
53	        context: &ProviderContext<'_>,
54	        request: &ProviderRequest<'_>,
55	    ) -> Result<ReleasePreflight, GraphError> {
56	        let adapter = adapter_for(request.id.package.ecosystem())?;
57	        let operation = registry_operation(request)?;
58	        let preflight = adapter.preflight(context, request.id, operation, request.artifacts)?;
59	        if matches!(preflight, ReleasePreflight::AlreadySatisfied { .. }) {
60	            warn_if_foreign_repository(adapter, context, request.id, operation);
61	        }
62	        Ok(preflight)
63	    }
64	
65	    fn defers_confirmation(&self, request: &ProviderRequest<'_>) -> bool {
66	        adapter_for(request.id.package.ecosystem()).is_ok_and(|adapter| adapter.defers_confirmation())
67	    }
68	
69	    fn issue(
70	        &self,
71	        context: &ProviderContext<'_>,
72	        request: &ProviderRequest<'_>,
73	        _effect: &EffectAuthorization<'_>,
74	    ) -> Result<(), GraphError> {
75	        let operation = registry_operation(request)?;
76	        let adapter = adapter_for(request.id.package.ecosystem())?;
77	        if !adapter.defers_confirmation() {
78	            return Err(GraphError::ReleaseInvariant {
79	                detail: format!("`{}` is confirmed as it is published", request.id),
80	            });
81	        }
82	        run_publish_client(adapter, context, request, operation)
83	    }
84	
85	    fn confirmation_window(&self, request: &ProviderRequest<'_>) -> Duration {
86	        match (registry_operation(request), adapter_for(request.id.package.ecosystem())) {
87	            (Ok(operation), Ok(adapter)) => visibility_window(adapter, operation),
88	            _ => Duration::ZERO,
89	        }
90	    }
91	
92	    fn publish(
93	        &self,
94	        context: &ProviderContext<'_>,
95	        request: &ProviderRequest<'_>,
96	        _effect: &EffectAuthorization<'_>,
97	    ) -> Result<ExactEvidence, GraphError> {
98	        let operation = registry_operation(request)?;
99	        let adapter = adapter_for(request.id.package.ecosystem())?;
100	        run_publish_client(adapter, context, request, operation)?;
101	        // Neither a zero exit nor the client's "already exists" text is a
102	        // receipt: a yanked version is not the version this intent authorized,
103	        // so only an exact observation may satisfy the operation.
104	        let confirmed = adapter.confirm(context, request.id, operation, request.artifacts)?;
105	        let waited = visibility_window(adapter, operation);
106	        require_registry_confirmation(
107	            confirmed.is_terminal_success(),
108	            &operation.package_name,
109	            &operation.version,
110	            waited,
111	        )?;
112	        confirmed
113	            .exact_evidence()
114	            .ok_or_else(|| GraphError::RegistryPublishUnconfirmed {
115	                package: operation.package_name.clone(),
116	                version: operation.version.clone(),
117	                waited,
118	            })
119	    }
120	}
121	
122	/// Adopting a version that is already published is by design (a rerun finishes a half-done release), but a version
123	/// whose registry entry names another repository is more likely someone else's package. Warns, never blocks.
124	fn warn_if_foreign_repository(
125	    adapter: &dyn RegistryEcosystem,
126	    context: &ProviderContext<'_>,
127	    id: &ReleaseOperationId,
128	    operation: &RegistryPublishOperation,
129	) {
130	    let Some(origin) = context.origin_endpoint() else {
131	        return;
132	    };
133	    let registry_repository = adapter.repository(context, operation);
134	    if let Some(warning) = repository::foreign_repository_warning(
135	        &id.package.to_string(),
136	        operation.version.render(),
137	        registry_repository.as_deref(),
138	        origin,
139	    ) {
140	        eprintln!("{warning}");
141	    }
142	}
143	
144	/// Runs the ecosystem's publish client. A failed publish stops here; a published and an already-existing version are
145	/// both left for the confirmation.
146	fn run_publish_client(
147	    adapter: &dyn RegistryEcosystem,
148	    context: &ProviderContext<'_>,
149	    request: &ProviderRequest<'_>,
150	    operation: &RegistryPublishOperation,
151	) -> Result<(), GraphError> {
152	    let output = adapter.publish(context, request.id, operation, request.artifacts)?;
153	    adapter
154	        .classify(&output)
155	        .map(|_outcome| ())
156	        .map_err(|source| GraphError::Registry {
157	            package: operation.package_name.clone(),
158	            source,
159	        })
160	}
161	
162	fn proceed() -> ReleasePreflight {
163	    ReleasePreflight::Proceed {
164	        proof: ProviderObservationV1::Absent
165	            .absent_proof()
166	            .expect("an absent observation mints an absent proof"),
167	    }
168	}
169	
170	fn registry_operation<'a>(request: &ProviderRequest<'a>) -> Result<&'a RegistryPublishOperation, GraphError> {
171	    match request.operation {
172	        PreparedOperation::RegistryPublish(operation) => Ok(operation),
173	        _ => Err(wrong_role(request.id, "registry publish")),
174	    }
175	}
176	
177	/// The one registry observation used by preflight and post-publish
178	/// confirmation, so the two can never disagree.
179	fn registry_observation<A: RegistryEcosystem + ?Sized>(
180	    adapter: &A,
181	    context: &ProviderContext<'_>,
182	    operation: &RegistryPublishOperation,
183	) -> Result<ProviderObservationV1, GraphError> {
184	    if !adapter.can_observe_versions() {
185	        return Ok(ProviderObservationV1::Indeterminate {
186	            cause: ProviderIndeterminateCause::UnsupportedProvider,
187	        });
188	    }
189	    policy::retry_observation_within(context.sleeper(), context.patience(), || {
190	        adapter.observe_once(context, operation)
191	    })
192	}
193	
194	/// The longest one publish command may run: the registry's configured `publish-timeout`, else the default.
195	fn publish_timeout(operation: &RegistryPublishOperation) -> Duration {
196	    operation.registry.publish_timeout.unwrap_or(timeouts::PUBLISH)
197	}
198	
199	/// How long this publish's version may take to show up: the registry's configured `confirm-timeout`, else the default.
200	fn visibility_window<A: RegistryEcosystem + ?Sized>(adapter: &A, operation: &RegistryPublishOperation) -> Duration {
201	    operation
202	        .registry
203	        .confirm_timeout
204	        .unwrap_or_else(|| policy::default_visibility_window(adapter.ecosystem()))
205	}
206	
207	/// The same observation, but an absence is treated as index-propagation lag
208	/// rather than an answer, for up to the registry's visibility window: this only
209	/// runs after a publish client reported the version as published or already there.
210	fn confirmed_registry_observation<A: RegistryEcosystem + ?Sized>(
211	    adapter: &A,
212	    context: &ProviderContext<'_>,
213	    operation: &RegistryPublishOperation,
214	) -> Result<ProviderObservationV1, GraphError> {
215	    policy::retry_within_window(context.sleeper(), visibility_window(adapter, operation), || {
216	        Ok(match adapter.observe_once(context, operation)? {
217	            Attempt::Settled(ProviderObservationV1::Absent) => Attempt::Transient {
218	                value: ProviderObservationV1::Absent,
219	                retry_after: None,
220	            },
221	            settled_or_transient => settled_or_transient,
222	        })
223	    })
224	}
225	
226	/// One ecosystem's registry client. This is the single place the release path
227	/// branches on [`Ecosystem`]: adding a registry means adding an adapter here,
228	/// not another match in preflight, dispatch, or confirmation.
229	pub(crate) trait RegistryEcosystem {
230	    fn ecosystem(&self) -> Ecosystem;
231	
232	    /// Whether a publish here is complete once the version is visible, so the run can issue the next publish while
233	    /// this one propagates. Not true where completion is more than visibility: PyPI compares a whole file set.
234	    fn defers_confirmation(&self) -> bool {
235	        false
236	    }
237	
238	    /// The repository the registry says this published version belongs to. Best effort: a registry that records
239	    /// none, or a read that fails, is `None`.
240	    fn repository(&self, _context: &ProviderContext<'_>, _operation: &RegistryPublishOperation) -> Option<String> {
241	        None
242	    }
243	
244	    /// Whether this registry exposes a query that proves an exact published
245	    /// version. `false` makes every observation `Indeterminate`, so a publish
246	    /// is never confirmed here and instead fails closed at the mandatory
247	    /// post-effect exact observation.
248	    fn can_observe_versions(&self) -> bool;
249	
250	    /// One observation attempt. Only called when [`Self::can_observe_versions`].
251	    fn observe_once(
252	        &self,
253	        context: &ProviderContext<'_>,
254	        operation: &RegistryPublishOperation,
255	    ) -> Result<Attempt<ProviderObservationV1>, GraphError>;
256	
257	    /// Runs the publish client and returns the output that decides the outcome.
258	    fn publish(
259	        &self,
260	        context: &ProviderContext<'_>,
261	        id: &ReleaseOperationId,
262	        operation: &RegistryPublishOperation,
263	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
264	    ) -> Result<CommandOutput, GraphError>;
265	
266	    fn classify(&self, output: &CommandOutput) -> Result<PublishOutcome, RegistryError>;
267	
268	    /// What the one fresh pre-effect observation authorizes.
269	    fn preflight(
270	        &self,
271	        context: &ProviderContext<'_>,
272	        id: &ReleaseOperationId,
273	        operation: &RegistryPublishOperation,
274	        _artifacts: Option<&VerifiedArtifactManifest<'_>>,
275	    ) -> Result<ReleasePreflight, GraphError> {
276	        match registry_observation(self, context, operation)? {
277	            // A registry with no query API at all has nothing to observe
278	            // before the effect; the post-effect confirmation fails closed.
279	            ProviderObservationV1::Indeterminate {
280	                cause: ProviderIndeterminateCause::UnsupportedProvider,
281	            } => Ok(proceed()),
282	            observation => preflight_from_observation(observation, id, RemoteConflict::RegistryVersionDiffers),
283	        }
284	    }
285	
286	    /// The observation that lets a finished publish be recorded. The client reported the version published or already
287	    /// there, so a registry that does not show it yet is lagging, and is waited on.
288	    fn confirm(
289	        &self,
290	        context: &ProviderContext<'_>,
291	        _id: &ReleaseOperationId,
292	        operation: &RegistryPublishOperation,
293	        _artifacts: Option<&VerifiedArtifactManifest<'_>>,
294	    ) -> Result<ProviderObservationV1, GraphError> {
295	        if self.can_observe_versions() {
296	            confirmed_registry_observation(self, context, operation)
297	        } else {
298	            registry_observation(self, context, operation)
299	        }
300	    }
301	}
302	
303	/// The repository the registry records for a published version of this package, if it records one and can be read.
304	pub(crate) fn recorded_repository(
305	    context: &ProviderContext<'_>,
306	    ecosystem: Ecosystem,
307	    operation: &RegistryPublishOperation,
308	) -> Option<String> {
309	    adapter_for(ecosystem).ok()?.repository(context, operation)
310	}
311	
312	/// The production adapter set, keyed by ecosystem.
313	pub(crate) fn adapter_for(ecosystem: Ecosystem) -> Result<&'static dyn RegistryEcosystem, GraphError> {
314	    match ecosystem {
315	        Ecosystem::Cargo => Ok(&CargoRegistry),
316	        Ecosystem::Npm => Ok(&NpmRegistry),
317	        Ecosystem::Pypi => Ok(&PypiRegistry),
318	        _ => Err(GraphError::UnsupportedRelease {
319	            feature: UnsupportedReleaseFeature::Ecosystem,
320	        }),
321	    }
322	}
323	
324	/// Runs an [`registry_argv::Argv`] built by the pure argv layer. This is the
325	/// only place an adapter touches [`callisto_model::CommandRunner`] --
326	/// everything about *what* to run was already decided by `registry_argv`.
327	fn run_argv(
328	    context: &ProviderContext<'_>,
329	    argv: &registry_argv::Argv,
330	    timeout: Duration,
331	) -> Result<CommandOutput, GraphError> {
332	    let args: Vec<&str> = argv.args.iter().map(String::as_str).collect();
333	    Ok(context
334	        .runner()
335	        .run_with_timeout(&argv.program, &args, &argv.cwd, timeout)?)
336	}
337	
338	/// Withheld from a build backend, which runs project code and needs none of them.
339	const RELEASE_CREDENTIALS: &[&str] = &[
340	    "ACTIONS_ID_TOKEN_REQUEST_TOKEN",
341	    "ACTIONS_ID_TOKEN_REQUEST_URL",
342	    "CARGO_REGISTRY_TOKEN",
343	    "GH_TOKEN",
344	    "GITHUB_TOKEN",
345	    "NPM_CONFIG_TOKEN",
346	    "NPM_CONFIG_USERCONFIG",
347	    "NPM_TOKEN",
348	    "NODE_AUTH_TOKEN",
349	    "PYPI_TOKEN",
350	    "TWINE_PASSWORD",
351	    "TWINE_USERNAME",
352	];
353	
354	fn run_build_argv(context: &ProviderContext<'_>, argv: &registry_argv::Argv) -> Result<CommandOutput, GraphError> {
355	    let args: Vec<&str> = argv.args.iter().map(String::as_str).collect();
356	    Ok(context.runner().run_with_timeout_env_filtered(
357	        &argv.program,
358	        &args,
359	        &argv.cwd,
360	        timeouts::PUBLISH,
361	        RELEASE_CREDENTIALS,
362	    )?)
363	}
364	
365	fn transient(
366	    cause: ProviderIndeterminateCause,
367	    retry_after: Option<std::time::Duration>,
368	) -> Attempt<ProviderObservationV1> {
369	    Attempt::Transient {
370	        value: ProviderObservationV1::Indeterminate { cause },
371	        retry_after,
372	    }
373	}
374	
375	fn settled(observation: ProviderObservationV1) -> Attempt<ProviderObservationV1> {
376	    Attempt::Settled(observation)
377	}
378	
379	/// Builds the sdist and wheel of a Python publish into `outdir`, for a build job that seals them.
380	pub(crate) fn build_python_into(
381	    context: &ProviderContext<'_>,
382	    operation: &RegistryPublishOperation,
383	    outdir: &std::path::Path,
384	) -> Result<(), GraphError> {
385	    PypiRegistry::build_into(context, operation, outdir)
386	}
387	
388	/// The plan-time gate: an ecosystem whose client cannot prove a version absent
389	/// could never mint the absence proof an effect needs, nor the exact evidence a
390	/// receipt needs, so the plan is refused here rather than at dispatch.
391	pub(crate) fn require_observable_registry(ecosystem: Ecosystem) -> Result<(), GraphError> {
392	    if !adapter_for(ecosystem)?.can_observe_versions() {
393	        return Err(GraphError::ReleasePreconditionUnmet {
394	            requirement: ReleasePreconditionRequirement::ObservableRegistryClient,
395	        });
396	    }
397	    Ok(())
398	}
399	
