113	/// Classifies one real `cargo info` run. There is no `--json`, so the two
114	/// answers cargo actually proves are read from its exit code and its text:
115	///
116	/// - exit 0 with a `version: VERSION` line for the requested version: `Exact`.
117	///   `cargo info` reports neither the index checksum nor the yank flag, so the
118	///   evidence says `None` for both rather than inventing them.
119	/// - exit 101 with ``could not find `NAME@VERSION` ``: `Absent`.
120	/// - anything else -- another exit code, another message (a network failure
121	///   prints ``failed to load source for dependency``), or a zero exit with no
122	///   matching version line: transient `Indeterminate`, retried by the bounded
123	///   policy. An unreachable registry must never read as an absence.
124	///
125	/// A *yanked* version reads as `Absent`, because `cargo info` cannot see yanks
126	/// and answers "could not find" for one. That fails closed rather than open:
127	/// the publish attempt that follows is refused by the registry, and since only
128	/// an `Exact` observation may satisfy an operation, the run ends in the typed
129	/// `RegistryPublishUnconfirmed` error instead of a receipt.
130	pub(super) fn classify_cargo_info(
131	    output: &CommandOutput,
132	    spec: &str,
133	    version: &Version,
134	) -> Attempt<ProviderObservationV1> {
135	    if output.success() {
136	        return if reports_version(&output.stdout, version) {
137	            settled(ProviderObservationV1::Exact {
138	                evidence: ProviderEvidenceV1::RegistryVersion {
139	                    version: version.clone(),
140	                    checksum: None,
141	                    yanked: None,
142	                },
143	            })
144	        } else {
145	            transient(ProviderIndeterminateCause::MalformedResponse, None)
146	        };
147	    }
148	    if output.exit_code == Some(101) && output.stderr.contains(&format!("could not find `{spec}`")) {
149	        return settled(ProviderObservationV1::Absent);
150	    }
151	    transient(ProviderIndeterminateCause::CommandFailed, None)
152	}
153	
154	/// The value of the `repository:` line `cargo info` prints, if the crate has one.
155	pub(super) fn cargo_info_repository(stdout: &str) -> Option<String> {
156	    stdout
157	        .lines()
158	        .find_map(|line| line.trim().strip_prefix("repository:"))
159	        .map(|value| value.trim().to_owned())
160	        .filter(|value| !value.is_empty())
161	}
162	
163	/// Whether cargo's `version: X ...` line names exactly the requested version.
164	pub(super) fn reports_version(stdout: &str, version: &Version) -> bool {
165	    stdout.lines().any(|line| {
166	        line.trim()
167	            .strip_prefix("version: ")
168	            .and_then(|rest| rest.strip_prefix(version.render()))
169	            .is_some_and(|rest| rest.is_empty() || rest.starts_with(char::is_whitespace))
170	    })
171	}
