176	/// The tagged releases on HEAD whose operations are not all observed satisfied: a rerun finishes them.
177	///
178	/// A tag proves only that the tag was created. Releases tagged on an older commit are settled and
179	/// never observed, so only a rerun at the release commit reaches the providers.
180	fn incomplete_tagged_releases<R: CommandRunner, D: DependencyResolver>(
181	    workspace: &Workspace<'_, R, D>,
182	    mode: LocalReleaseSource,
183	) -> Result<std::collections::BTreeSet<ReleasePackageId>, GraphError> {
184	    let head = workspace.git_access().head_sha()?;
185	    let tagged: std::collections::BTreeSet<ReleasePackageId> =
186	        crate::commands::release_decision::releases_tagged_at(workspace, &head)?
187	            .into_iter()
188	            .map(|entry| entry.package)
189	            .collect();
190	    if tagged.is_empty() {
191	        return Ok(tagged);
192	    }
193	    // Without an `origin` push URL a preview cannot observe anything, so it cannot call a tagged release finished.
194	    if mode == LocalReleaseSource::Preview && optional_git_remote(&workspace.root, workspace.runner)?.is_none() {
195	        return Ok(tagged);
196	    }
197	    let profile = ExecutionTrustProfileV1::GitCommit;
198	    let source = match mode {
199	        LocalReleaseSource::Preview => SourceIdentity::GitCommit { sha: head },
200	        LocalReleaseSource::Trusted => observe_source(workspace, profile, ReleaseCheckout::AnyHead)?,
201	    };
202	    // The roster a run would plan with every tagged release still open, so a dependency left untagged by the
203	    // failed run is part of it and the dependency checks see the same packages as the real derivation.
204	    let Some(decision) = crate::commands::release_decision::derive_release_roster(workspace, &[], &tagged)? else {
205	        return Ok(Default::default());
206	    };
207	    let (_, prepared) =
208	        derive_release_intent_with_prepared(workspace, &decision, source, profile, None, &mut Vec::new())?;
209	    Ok(unsatisfied_packages(
210	        &workspace.root,
211	        workspace.runner,
212	        &prepared,
213	        &tagged,
214	    ))
215	}
