237	fn refuse_a_crate_crates_io_would_reject<R: CommandRunner, D: DependencyResolver>(
238	    workspace: &Workspace<'_, R, D>,
239	    decision: &callisto_model::ReleaseDecisionV1,
240	) -> Result<(), GraphError> {
241	    for id in first_release_packages(workspace, decision)? {
242	        let Some(package) = crate::commands::release_decision::workspace_package(workspace, &id) else {
243	            continue;
244	        };
245	        if !package.publish_to.contains(&PublishTarget::CratesIo) {
246	            continue;
247	        }
248	        let Some(manifest) = package
249	            .canonical_manifests()
250	            .find(|manifest| manifest.format == ManifestFormat::CargoToml)
251	            .map(|manifest| manifest.path.clone())
252	        else {
253	            continue;
254	        };
255	        let Some(text) = callisto_manifests::read_manifest_text(&workspace.root)(&manifest)? else {
256	            continue;
257	        };
258	        let document = callisto_manifests::parse_manifest(&manifest, &text)?;
259	        let root = callisto_manifests::enclosing_workspace_manifest(&workspace.root, &manifest, &document)?;
260	        let root_document = match root {
261	            Some(root) => callisto_manifests::read_manifest_text(&workspace.root)(&root)?
262	                .map(|text| callisto_manifests::parse_manifest(&root, &text))
263	                .transpose()?,
264	            None => None,
265	        };
266	        let missing = callisto_manifests::missing_crates_io_metadata(&document, root_document.as_ref());
267	        if !missing.is_empty() {
268	            return Err(GraphError::ReleaseMetadataMissing {
269	                package: id.to_string(),
270	                missing: missing.join(" or "),
271	            });
272	        }
273	    }
274	    Ok(())
275	}
