312	/// Refuses to tag a version the registry already holds while its package has moved on since the commit that set it.
313	///
314	/// A release that stopped after publishing leaves exactly this state. A rerun on a later commit would tag code that
315	/// was never published, so it finishes from the version commit instead. Nothing is observed unless a package moved.
316	fn refuse_a_published_version_left_behind<R: CommandRunner, D: DependencyResolver>(
317	    workspace: &Workspace<'_, R, D>,
318	    decision: &callisto_model::ReleaseDecisionV1,
319	    resumable: &std::collections::BTreeSet<ReleasePackageId>,
320	    source: &SourceIdentity,
321	    profile: ExecutionTrustProfileV1,
322	    mode: LocalReleaseSource,
323	) -> Result<(), GraphError> {
324	    let moved = super::version_commit::packages_moved_past_their_version(workspace, decision, resumable)?;
325	    // Without an `origin` push URL a preview cannot observe the registry either.
326	    if moved.is_empty()
327	        || (mode == LocalReleaseSource::Preview && optional_git_remote(&workspace.root, workspace.runner)?.is_none())
328	    {
329	        return Ok(());
330	    }
331	    let (_, prepared) =
332	        derive_release_intent_with_prepared(workspace, decision, source.clone(), profile, None, &mut Vec::new())?;
333	    let among = moved.iter().map(|moved| moved.package.clone()).collect();
334	    let published = published_packages(&workspace.root, workspace.runner, &prepared, &among)?;
335	    match moved.into_iter().find(|moved| published.contains(&moved.package)) {
336	        Some(moved) => {
337	            let (since, fix) = match moved.version_commit {
338	                Some(commit) => {
339	                    let short: String = commit.chars().take(12).collect();
340	                    (
341	                        format!("{short}, the commit that set it"),
342	                        format!("Check out {short} (`git checkout --detach {short}`) and run `callisto release` again to finish that release. Releasing from here would tag code that was not published."),
343	                    )
344	                }
345	                None => (
346	                    "the commit that set it, which this history does not show".to_owned(),
347	                    "Check out the commit that was published and run `callisto release` again, or tag that commit by hand. Releasing from here could tag code that was not published.".to_owned(),
348	                ),
349	            };
350	            Err(GraphError::ReleasePublishedVersionMoved {
351	                package: moved.package.to_string(),
352	                version: moved.version,
353	                since,
354	                fix,
355	            })
356	        }
357	        None => Ok(()),
358	    }
359	}
