361	/// [`plan_local_release`] over an already-loaded workspace, e.g. one built from an in-memory config.
362	///
363	/// This looks at no registry for a name another project owns, so a caller that must stay offline, such as the plan
364	/// `init` previews, can use it; [`plan_local_release`] does look.
365	pub fn plan_workspace_release<R: CommandRunner, D: DependencyResolver>(
366	    workspace: &Workspace<'_, R, D>,
367	    selections: &[ReleasePackageId],
368	    mode: LocalReleaseSource,
369	) -> Result<Option<LocalReleasePlan>, GraphError> {
370	    plan_release(workspace, selections, mode, false)
371	}
372	
373	/// [`plan_local_release`] over an already-loaded workspace: the same plan, including the registry checks, without
374	/// loading the workspace again.
375	pub fn plan_loaded_release<R: CommandRunner, D: DependencyResolver>(
376	    workspace: &Workspace<'_, R, D>,
377	    selections: &[ReleasePackageId],
378	    mode: LocalReleaseSource,
379	) -> Result<Option<LocalReleasePlan>, GraphError> {
380	    plan_release(workspace, selections, mode, true)
381	}
382	
383	fn plan_release<R: CommandRunner, D: DependencyResolver>(
384	    workspace: &Workspace<'_, R, D>,
385	    selections: &[ReleasePackageId],
386	    mode: LocalReleaseSource,
387	    check_taken_names: bool,
388	) -> Result<Option<LocalReleasePlan>, GraphError> {
389	    let resumable = incomplete_tagged_releases(workspace, mode)?;
390	    let Some(decision) = crate::commands::release_decision::derive_release_roster(workspace, selections, &resumable)?
391	    else {
392	        return Ok(None);
393	    };
394	    let profile = ExecutionTrustProfileV1::GitCommit;
395	    let source = match mode {
396	        LocalReleaseSource::Preview => SourceIdentity::GitCommit {
397	            sha: workspace.git_access().head_sha()?,
398	        },
399	        LocalReleaseSource::Trusted => observe_source(workspace, profile, ReleaseCheckout::AnyHead)?,
400	    };
401	    if check_taken_names {
402	        refuse_a_crate_crates_io_would_reject(workspace, &decision)?;
403	        refuse_a_name_another_project_owns(workspace, &decision, &source, profile, mode)?;
404	    }
405	    refuse_a_published_version_left_behind(workspace, &decision, &resumable, &source, profile, mode)?;
406	    // A local run is its own orchestration: slots bind to the source commit.
407	    let artifact_policy = match (&workspace.config.product_release, &source) {
408	        (Some(release), SourceIdentity::GitCommit { sha }) if !release.artifacts.is_empty() => {
409	            release.forge_repository.clone().map(|repository| ArtifactBuildPolicy {
410	                repository,
411	                workflow_path: callisto_model::RELEASE_COORDINATOR_WORKFLOW_PATH.to_owned(),
412	                workflow_commit: sha.clone(),
413	            })
414	        }
415	        _ => None,
416	    };
417	    let remote = match mode {
418	        LocalReleaseSource::Preview => GitRemoteRequirement::OptionalForPreview,
419	        LocalReleaseSource::Trusted => GitRemoteRequirement::Required,
420	    };
421	    let mut diagnostics = Vec::new();
422	    let intent = derive_release_intent(
423	        workspace,
424	        &decision,
425	        source.clone(),
426	        profile,
427	        artifact_policy.as_ref(),
428	        remote,
429	        &mut diagnostics,
430	    )?;
431	    let tags_unbound = mode == LocalReleaseSource::Preview
432	        && intent
433	            .operations
434	            .iter()
435	            .any(|operation| operation.id().role == callisto_model::ReleaseOperationRole::Tag)
436	        && optional_git_remote(&workspace.root, workspace.runner)?.is_none();
437	    if mode == LocalReleaseSource::Trusted && observe_source(workspace, profile, ReleaseCheckout::AnyHead)? != source {
438	        return Err(GraphError::ReleaseIntentStale {
439	            reason: StaleReason::source_identity_changed(),
440	        });
441	    }
442	    Ok(Some(LocalReleasePlan {
443	        intent,
444	        tags_unbound,
445	        diagnostics,
446	    }))
447	}
