160	/// Derives the intent for every unreleased package (or exactly `selections`).
161	///
162	/// This is the one plan derivation behind both `callisto release --dry-run`
163	/// and `callisto release`; `None` means nothing is unreleased.
164	pub fn plan_local_release<L: ProjectLocator, R: CommandRunner>(
165	    root: &Path,
166	    locator: &L,
167	    runner: &R,
168	    selections: &[ReleasePackageId],
169	    mode: LocalReleaseSource,
170	) -> Result<Option<LocalReleasePlan>, GraphError> {
171	    let root = canonical_root(root)?;
172	    let workspace = Workspace::load(root, locator, runner)?;
173	    plan_release(&workspace, selections, mode, true)
174	}
