277	/// Refuses a first release whose name another project already owns.
278	///
279	/// A package this repository has never tagged has no history here, so a version of it that the registry already holds
280	/// under a different repository is that project's, not ours; adopting it would tag this commit as their release.
281	/// A package that has a tag is left alone: its published versions are its own history.
282	fn refuse_a_name_another_project_owns<R: CommandRunner, D: DependencyResolver>(
283	    workspace: &Workspace<'_, R, D>,
284	    decision: &callisto_model::ReleaseDecisionV1,
285	    source: &SourceIdentity,
286	    profile: ExecutionTrustProfileV1,
287	    mode: LocalReleaseSource,
288	) -> Result<(), GraphError> {
289	    let first_releases = first_release_packages(workspace, decision)?;
290	    // Without an `origin` push URL a preview cannot tell whose repository the registry names.
291	    if first_releases.is_empty()
292	        || (mode == LocalReleaseSource::Preview && optional_git_remote(&workspace.root, workspace.runner)?.is_none())
293	    {
294	        return Ok(());
295	    }
296	    let (_, prepared) =
297	        derive_release_intent_with_prepared(workspace, decision, source.clone(), profile, None, &mut Vec::new())?;
298	    match names_taken_by_other_projects(&workspace.root, workspace.runner, &prepared, &first_releases)?
299	        .into_iter()
300	        .next()
301	    {
302	        Some(taken) => Err(GraphError::ReleaseNameTaken {
303	            package: taken.package.to_string(),
304	            version: taken.version,
