358	    let fixed = groups.fixed_of.iter().map(|(member, group)| ("fixed", member, group));
359	    let linked = groups.linked_of.iter().map(|(member, group)| ("linked", member, group));
360	    // `member` keys are already canonical (`GroupTable::resolve` resolved
