444	/// The commit has the shape of a version commit: it wrote the decision, consumed a changeset, and touched only the
445	/// paths a version commit may touch.
446	fn require_version_commit_shape<R: CommandRunner, D: DependencyResolver>(
447	    workspace: &Workspace<'_, R, D>,
448	    release_commit: &CommitSha,
449	    changed: &[(String, String)],
450	    decision_path: &str,
451	) -> Result<(), GraphError> {
452	    let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;
453	
454	    // The decision must be freshly authored as part of *this* commit, not a
455	    // stale leftover an earlier release already committed and this one never
456	    // touched -- otherwise a commit that changes nothing real could still
457	    // carry forward a prior, unrelated decision's authority.
458	    let decision_freshly_written = changed
459	        .iter()
460	        .any(|(status, path)| path == decision_path && matches!(status.as_str(), "A" | "M"));
461	    if !decision_freshly_written {
462	        return Err(GraphError::ReleaseCommitVerificationFailed {
463	            commit: release_commit.clone(),
464	            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
465	        });
466	    }
467	
468	    // A cheap, independent sanity check that this commit is a real version
469	    // application and not just a hand-crafted decision file: some real
470	    // changeset was actually consumed. The decision's own entries, not this
471	    // changeset's content, remain the sole authority verified below.
472	    let consumed_a_changeset = changed
473	        .iter()
474	        .any(|(status, path)| status == "D" && is_changeset_path(path, &changeset_dir));
475	    if !consumed_a_changeset {
476	        return Err(GraphError::ReleaseCommitVerificationFailed {
477	            commit: release_commit.clone(),
478	            reason: CommitVerificationFailure::NoChangesetConsumed,
479	        });
480	    }
481	
482	    // A version commit changes versions and what records them, nothing else. Any other path (build scripts, source,
483	    // a package manager's `.npmrc` or `.cargo/config.toml`, `callisto.toml`, an action) could change what is published
484	    // or where, under the cover of a bot-authored diff.
485	    let changelogs = workspace
486	        .graph
487	        .packages()
488	        .filter_map(|package| package.changelog.as_deref())
489	        .map(normalized_git_path)
490	        .collect::<Result<std::collections::BTreeSet<_>, _>>()?;
491	    for (_, path) in changed {
492	        if !is_version_commit_path(path, decision_path, &changeset_dir, &changelogs) {
493	            return Err(GraphError::ReleaseCommitVerificationFailed {
494	                commit: release_commit.clone(),
495	                reason: CommitVerificationFailure::UnexpectedPath { path: path.clone() },
496	            });
497	        }
498	    }
499	    Ok(())
500	}
