502	/// The decision file as the release commit holds it. Its own deserializer rejects entries that do not match its digest.
503	fn read_committed_decision<R: CommandRunner, D: DependencyResolver>(
504	    workspace: &Workspace<'_, R, D>,
505	    release_commit: &CommitSha,
506	    decision_path: &std::path::Path,
507	    decision_path_str: &str,
508	) -> Result<ReleaseDecisionV1, GraphError> {
509	    let decision_source = git_file(
510	        workspace.runner,
511	        &workspace.root,
512	        release_commit.as_str(),
513	        decision_path_str,
514	    )?;
515	    serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
516	        path: decision_path.to_path_buf(),
517	        message: error.to_string(),
