521	/// Every package the decision claims has its changelog and manifest in the diff with exactly the claimed version, and
522	/// no package the decision does not claim changed version.
523	fn require_manifests_match_decision<R: CommandRunner, D: DependencyResolver>(
524	    workspace: &Workspace<'_, R, D>,
525	    release_commit: &CommitSha,
526	    parent: &str,
527	    changed: &[(String, String)],
528	    decision: &ReleaseDecisionV1,
529	) -> Result<(), GraphError> {
530	    let claimed = decision
531	        .entries
532	        .iter()
533	        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
534	        .collect::<std::collections::BTreeMap<_, _>>();
535	
536	    let changed_paths = changed
537	        .iter()
538	        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
539	        .collect::<std::collections::BTreeSet<_>>();
540	
541	    // Every canonical manifest path this workspace currently declares, in
542	    // the exact order `workspace.graph.packages()` and
543	    // `Package::canonical_manifests()` yield -- both are backed by ordered
544	    // (`BTreeMap`/`Vec`) storage with no interior mutation between calls, so
545	    // the second traversal below visits the same (package, manifest) pairs
546	    // in the same order. That lets it zip the batched `before`/`after`
547	    // results back on by position instead of re-keying by path, which would
548	    // misbehave if two packages ever declared an identical manifest path.
549	    let manifest_queries: Vec<(String, Ecosystem)> = workspace
550	        .graph
551	        .packages()
552	        .flat_map(Package::canonical_manifests)
553	        .map(|manifest| Ok((normalized_git_path(&manifest.path)?, manifest.ecosystem())))
554	        .collect::<Result<_, GraphError>>()?;
555	    // Each Cargo manifest may inherit its version from a workspace manifest above it, so those are fetched too.
556	    let mut query_path_list: Vec<String> = manifest_queries.iter().map(|(path, _)| path.clone()).collect();
557	    for (path, _) in manifest_queries
558	        .iter()
559	        .filter(|(_, ecosystem)| *ecosystem == Ecosystem::Cargo)
560	    {
561	        for candidate in callisto_manifests::workspace_manifest_candidates(&workspace.root, std::path::Path::new(path))?
562	        {
563	            let candidate = normalized_git_path(&candidate)?;
564	            if !query_path_list.contains(&candidate) {
565	                query_path_list.push(candidate);
566	            }
567	        }
568	    }
569	    let query_paths: Vec<&str> = query_path_list.iter().map(String::as_str).collect();
570	
571	    // Exactly two `git cat-file --batch` subprocess invocations total (one
572	    // per commit), regardless of how many canonical manifests the
573	    // workspace has -- replaces what was previously 2*N separate `git
574	    // show` spawns (one `manifest_version_at` call per manifest per
575	    // commit).
576	    let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, parent, &query_paths)?;
577	    let after_blobs =
578	        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
579	    let before = CommitBlobs::new(workspace.runner, &workspace.root, parent, &query_paths, before_blobs);
580	    let after = CommitBlobs::new(
581	        workspace.runner,
582	        &workspace.root,
583	        release_commit.as_str(),
584	        &query_paths,
585	        after_blobs,
586	    );
587	    let before_versions = resolve_batch_versions(&before, &manifest_queries)?;
588	    let after_versions = resolve_batch_versions(&after, &manifest_queries)?;
589	
590	    let mut observed = std::collections::BTreeSet::new();
591	    let mut manifest_index = 0usize;
592	    for package in workspace.graph.packages() {
593	        let package_ids = release_package_ids(&workspace.identity, package)?;
594	        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
595	        if package_is_claimed {
596	            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
597	                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
598	            })?;
599	            let changelog = normalized_git_path(changelog)?;
600	            if !changed_paths.contains(changelog.as_str()) {
601	                return Err(GraphError::ReleaseCommitVerificationFailed {
602	                    commit: release_commit.clone(),
603	                    reason: CommitVerificationFailure::ChangelogNotTouched,
604	                });
605	            }
606	        }
607	        for id in package_ids {
608	            let before = &before_versions[manifest_index];
609	            let after = &after_versions[manifest_index];
610	            manifest_index += 1;
611	            let changed_version = before.version != after.version;
612	            match claimed.get(&id) {
613	                Some(target_version) => {
614	                    if !changed_paths.contains(after.authority.to_string_lossy().as_ref()) {
615	                        return Err(GraphError::ReleaseCommitVerificationFailed {
616	                            commit: release_commit.clone(),
617	                            reason: CommitVerificationFailure::ManifestNotInDiff,
618	                        });
619	                    }
620	                    if !changed_version || &after.version != target_version {
621	                        return Err(GraphError::ReleaseCommitVerificationFailed {
622	                            commit: release_commit.clone(),
623	                            reason: CommitVerificationFailure::ManifestVersionMismatch,
624	                        });
625	                    }
626	                    observed.insert(id);
627	                }
628	                None => {
629	                    if changed_version {
630	                        // A changed version the committed decision never
631	                        // claimed is not this commit's authority -- fail
632	                        // closed rather than trust a partial match.
633	                        return Err(GraphError::ReleaseCommitVerificationFailed {
634	                            commit: release_commit.clone(),
635	                            reason: CommitVerificationFailure::UnclaimedVersionChange,
636	                        });
637	                    }
638	                }
639	            }
640	        }
641	    }
642	    if observed.len() != claimed.len() {
643	        return Err(GraphError::ReleaseCommitVerificationFailed {
644	            commit: release_commit.clone(),
645	            reason: CommitVerificationFailure::ClaimedPackageNotObserved,
646	        });
647	    }
648	    Ok(())
