206	fn derive_release_inputs_with<R: CommandRunner, D: DependencyResolver>(
207	    workspace: &Workspace<'_, R, D>,
208	    decision: &ReleaseDecisionV1,
209	    source: SourceIdentity,
210	    artifact_policy: Option<&ArtifactBuildPolicy>,
211	    remote: GitRemoteRequirement,
212	    diagnostics: &mut Vec<Diagnostic>,
213	) -> Result<DerivedReleaseInputs, GraphError> {
214	    if workspace
215	        .config
216	        .product_release
217	        .as_ref()
218	        .is_some_and(|release| release.forge_repository.is_none())
219	    {
220	        return Err(GraphError::ReleaseForgeRepositoryMissing);
221	    }
222	    let mut package_inputs = Vec::new();
223	    let Selection {
224	        selected,
225	        package_ids,
226	        owners,
227	    } = select_packages(workspace, decision)?;
228	    require_dependencies_selected(workspace, &selected, &package_ids)?;
229	    let all_packages: Vec<_> = workspace.graph.packages().map(|package| package.id.clone()).collect();
230	    let publish_edges = PublishEdgeFilter::new(
231	        &package_ids.keys().cloned().collect(),
232	        &all_packages,
233	        |id: &callisto_model::PackageId| {
234	            workspace
235	                .graph
236	                .dependencies_of(id)
237	                .map(|edge| (edge.to.clone(), edge.kind))
238	                .collect()
239	        },
240	    )?;
241	
242	    let git_remote = prepare_remote(workspace, &selected, artifact_policy, remote)?;
243	
244	    let mut ops = Ops::default();
245	    build_publish_leaves(workspace, &selected, git_remote.as_ref(), &mut package_inputs, &mut ops)?;
246	    link_publish_prerequisites(workspace, &selected, &package_ids, &publish_edges, &mut ops)?;
247	    add_tags(&selected, &package_ids, &owners, &source, &mut ops)?;
248	    add_forge_releases(workspace, &selected, &owners, &mut ops)?;
249	    let artifact_slots = add_artifact_uploads(workspace, &selected, &owners, artifact_policy, &mut ops, diagnostics)?;
250	    add_forge_publishes(&selected, &owners, &mut ops)?;
251	
252	    Ok((
253	        ReleaseInputSnapshotV1::new(source, package_inputs)?,
254	        canonical_operation_order(ops.operations)?,
255	        ops.prepared,
256	        git_remote,
257	        artifact_slots,
258	    ))
259	}
