261	fn select_packages<'w, R: CommandRunner, D: DependencyResolver>(
262	    workspace: &'w Workspace<'_, R, D>,
263	    decision: &ReleaseDecisionV1,
264	) -> Result<Selection<'w>, GraphError> {
265	    let mut selected = BTreeMap::new();
266	    let mut package_ids = BTreeMap::<callisto_model::PackageId, Vec<ReleasePackageId>>::new();
267	    let mut owners = Owners::new();
268	    for package in workspace.graph.packages() {
269	        let ids = crate::commands::release_decision::release_package_ids(&workspace.identity, package)?;
270	        if let Some(owner) = ids
271	            .iter()
272	            .find(|id| decision.entries.iter().any(|entry| &entry.package == *id))
273	        {
274	            owners.insert(package.id.clone(), owner.clone());
275	        }
276	        // One canonical manifest per ecosystem is the expected shape, but
277	        // dedup defensively -- `release_package_ids` maps every canonical
278	        // manifest, and two manifests sharing an ecosystem would otherwise
279	        // select/push the same identity twice.
280	        for id in ids.into_iter().collect::<BTreeSet<_>>() {
281	            if let Some(entry) = decision.entries.iter().find(|entry| entry.package == id) {
282	                selected.insert(id.clone(), (package, entry.target_version.clone()));
283	                package_ids.entry(package.id.clone()).or_default().push(id);
284	            }
285	        }
286	    }
287	    for entry in &decision.entries {
288	        let id = &entry.package;
289	        if !selected.contains_key(id) {
290	            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
291	        }
292	    }
293	    Ok(Selection {
294	        selected,
295	        package_ids,
296	        owners,
297	    })
298	}
