300	fn prepare_remote<R: CommandRunner, D: DependencyResolver>(
301	    workspace: &Workspace<'_, R, D>,
302	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
303	    artifact_policy: Option<&ArtifactBuildPolicy>,
304	    remote: GitRemoteRequirement,
305	) -> Result<Option<PreparedGitRemote>, GraphError> {
306	    let requires_git_remote = selected.values().any(|(package, _)| {
307	        package
308	            .publish_to
309	            .iter()
310	            .any(|target| !matches!(target, PublishTarget::None))
311	    });
312	    let git_remote = match (requires_git_remote, remote) {
313	        (false, _) => None,
314	        (true, GitRemoteRequirement::Required) => Some(prepared_git_remote(&workspace.root, workspace.runner)?),
315	        (true, GitRemoteRequirement::OptionalForPreview) => optional_git_remote(&workspace.root, workspace.runner)?,
316	    };
317	    if let Some(policy) = artifact_policy {
318	        match git_remote.as_ref().and_then(|remote| remote.github_repository.as_ref()) {
319	            Some(remote) if remote != &policy.repository => {
320	                return Err(GraphError::ReleaseArtifactRepositoryMismatch {
321	                    configured: policy.repository.clone(),
322	                    remote: remote.clone(),
323	                });
324	            }
325	            Some(_) => {}
326	            // A preview has no effect to protect and `origin` is optional for it; the run itself still needs one.
327	            None if git_remote.is_none() && remote == GitRemoteRequirement::OptionalForPreview => {}
328	            None => {
329	                return Err(GraphError::ReleasePreconditionUnmet {
330	                    requirement: ReleasePreconditionRequirement::GitHubRemote,
331	                });
332	            }
333	        }
334	    }
335	    Ok(git_remote)
336	}
