338	/// A prerelease publishes under the tag its first identifier names (`1.0.0-beta.2` -> `beta`), `next` when that is not a
339	/// plain word, and never `latest`; a stable version takes the registry default.
340	fn npm_dist_tag(version: &Version) -> Option<String> {
341	    if !version.is_prerelease() {
342	        return None;
343	    }
344	    let prerelease = version.render().split_once('-').map_or("", |(_, rest)| rest);
345	    let label: String = prerelease
346	        .chars()
347	        .take_while(char::is_ascii_alphabetic)
348	        .collect::<String>()
349	        .to_ascii_lowercase();
350	    Some(if label.is_empty() || label == "latest" {
351	        "next".to_string()
352	    } else {
353	        label
354	    })
355	}
356	
357	/// One registry publish per package target, with its platform publishes, and each package's input fingerprint.
358	fn build_publish_leaves<R: CommandRunner, D: DependencyResolver>(
359	    workspace: &Workspace<'_, R, D>,
360	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
361	    git_remote: Option<&PreparedGitRemote>,
362	    package_inputs: &mut Vec<ReleasePackageInputV1>,
363	    ops: &mut Ops,
364	) -> Result<(), GraphError> {
365	    let Ops {
366	        operations,
367	        prepared,
368	        index: OpIndex {
369	            publishes_by_package,
370	            platforms_by_publish,
371	            ..
372	        },
373	    } = ops;
374	
375	    // First construct leaves so dependency prerequisites can refer only to
376	    // exact selected release identities, never PackageId's wildcard matcher.
377	    for (id, (package, version)) in selected {
378	        if crate::commands::snapshot::is_snapshot_version(version) {
379	            return Err(GraphError::ReleaseSelectionInvalid {
380	                package: id.clone(),
381	                reason: ReleaseSelectionInvalidReason::SnapshotVersion,
382	            });
383	        }
384	        let produces_tag = package
385	            .publish_to
386	            .iter()
387	            .any(|target| !matches!(target, PublishTarget::None));
388	        let fingerprint = package_fingerprint(
389	            workspace,
390	            id,
391	            package,
392	            version,
393	            produces_tag.then_some(git_remote).flatten(),
394	        )?;
395	        package_inputs.push(ReleasePackageInputV1 {
396	            package: id.clone(),
397	            fingerprint,
398	        });
399	
400	        let mut publishes = Vec::new();
401	        for target in &package.publish_to {
402	            if !target.is_implemented() {
403	                return Err(GraphError::PublishTargetNotImplemented {
404	                    package: id.clone(),
405	                    target: target.config_str(),
406	                });
407	            }
408	            if target.ecosystem() == Some(id.ecosystem()) {
409	                super::provider::registry::require_observable_registry(id.ecosystem())?;
410	                let binding = prepared_registry_binding(workspace, target, &package.id)?;
411	                let binding_id = RegistryBindingId::new(binding.key.as_str(), binding.identity.clone())?;
412	                let operation =
413	                    ReleaseOperation::registry_publish(id.clone(), version.clone(), binding_id.clone(), Vec::new())?;
414	                // A durable registry operation must have one exact endpoint
415	                // binding. The model-level operation identity currently has
416	                // only a registry key, so reject a second target that would
417	                // collapse to the same operation until the typed binding
418	                // identity is added there.
419	                if prepared.contains_key(operation.id()) {
420	                    return Err(GraphError::ReleaseSelectionInvalid {
421	                        package: id.clone(),
