491	fn link_publish_prerequisites<R: CommandRunner, D: DependencyResolver>(
492	    workspace: &Workspace<'_, R, D>,
493	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
494	    package_ids: &BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
495	    publish_edges: &PublishEdgeFilter,
496	    ops: &mut Ops,
497	) -> Result<(), GraphError> {
498	    let Ops {
499	        operations,
500	        index: OpIndex {
501	            publishes_by_package,
502	            platforms_by_publish,
503	            ..
504	        },
505	        ..
506	    } = ops;
507	
508	    // Replace each publish leaf with prerequisites from selected dependency
509	    // packages, ordered by the shared publish edge filter.
510	    for (id, (package, _)) in selected {
511	        let mut prerequisites = BTreeSet::new();
512	        for edge in workspace.graph.dependencies_of(&package.id) {
513	            if !publish_edges.allows(&package.id, &edge.to, edge.kind) {
514	                continue;
515	            }
516	            // The edge names the dependency's distribution in the declaring manifest's ecosystem, so a Cargo
517	            // dependent waits for the dependency's crate, not for its npm package. No such distribution means the
518	            // edge was resolved some other way, so it waits for all of them.
519	            let ecosystem = crate::cascade::manifest_ecosystem(&edge.from_manifest);
520	            let dependency_ids = package_ids.get(&edge.to).map(Vec::as_slice).unwrap_or_default();
521	            let touched: Vec<&ReleasePackageId> = dependency_ids
522	                .iter()
523	                .filter(|dependency_release_id| dependency_release_id.ecosystem() == ecosystem)
524	                .collect();
525	            let dependency_ids: Vec<&ReleasePackageId> = if touched.is_empty() {
526	                dependency_ids.iter().collect()
527	            } else {
528	                touched
529	            };
530	            for dependency_release_id in dependency_ids {
531	                prerequisites.extend(
532	                    publishes_by_package
533	                        .get(dependency_release_id)
534	                        .into_iter()
535	                        .flatten()
536	                        .cloned(),
537	                );
538	            }
539	        }
540	        for publish_id in publishes_by_package.get(id).into_iter().flatten() {
541	            let operation = operations.get(publish_id).expect("publish operation was constructed");
542	            let mut prerequisites = prerequisites.clone();
543	            prerequisites.extend(platforms_by_publish.get(publish_id).into_iter().flatten().cloned());
544	            let replacement = ReleaseOperation::new(operation.id().clone(), prerequisites.into_iter().collect())?;
545	            operations.insert(publish_id.clone(), replacement);
546	        }
547	    }
548	    Ok(())
549	}
550	
551	fn add_tags(
552	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
553	    package_ids: &BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
554	    owners: &Owners,
555	    source: &SourceIdentity,
556	    ops: &mut Ops,
557	) -> Result<(), GraphError> {
558	    let Ops {
559	        operations,
560	        prepared,
561	        index,
562	    } = ops;
563	
564	    for (id, (package, version)) in owned(selected, owners) {
565	        if !package
566	            .publish_to
567	            .iter()
568	            .any(|target| !matches!(target, PublishTarget::None))
569	        {
570	            continue;
571	        }
572	        let tag = ReleaseOperation::tag(
573	            id.clone(),
574	            version.clone(),
575	            index.tag_prerequisites(
576	                package_ids
577	                    .get(&package.id)
578	                    .map_or(std::slice::from_ref(id), Vec::as_slice),
579	            ),
580	        )?;
581	        let tag_name = package
582	            .tag_template
583	            .clone()
584	            .unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))
585	            .render(version);
586	        let target = match source {
587	            SourceIdentity::GitCommit { sha } => sha.clone(),
588	            SourceIdentity::HermeticContent { .. } => {
589	                return Err(GraphError::UnsupportedRelease {
590	                    feature: UnsupportedReleaseFeature::SourceIdentity,
591	                })
592	            }
593	        };
594	        prepared.insert(
595	            tag.id().clone(),
596	            PreparedOperation::Tag(TagOperation {
597	                annotation: format!("Release {tag_name}"),
598	                name: tag_name,
599	                target,
600	            }),
601	        );
602	        index.tag_by_package.insert(id.clone(), tag.id().clone());
603	        operations.insert(tag.id().clone(), tag);
604	    }
605	    Ok(())
606	}
