608	/// The other members of `package`'s fixed group that keep a changelog, with the name each is shown by in release notes.
609	fn fixed_group_changelogs<'w, R: CommandRunner, D: DependencyResolver>(
610	    workspace: &'w Workspace<'_, R, D>,
611	    package: &callisto_model::Package,
612	) -> Vec<(String, &'w std::path::Path)> {
613	    let groups = &workspace.config.groups;
614	    let Some(group) = groups.fixed_of.get(&package.id) else {
615	        return Vec::new();
616	    };
617	    workspace
618	        .graph
619	        .packages()
620	        .filter(|member| member.id != package.id && groups.fixed_of.get(&member.id) == Some(group))
621	        .filter_map(|member| Some((member.canonical_id().to_string(), member.changelog.as_deref()?)))
622	        .collect()
623	}
