            Ok(match Self::remote_once(context, operation)? {
                Attempt::Settled(remote) => Attempt::Settled(observed(remote)?),
                Attempt::Transient { value, retry_after } => Attempt::Transient {
                    value: observed(value)?,
                    retry_after,
                },
            })
        })
